<script>
  import {onDestroy,onMount} from 'svelte';
  import { recordCompletion } from '../lib/game/progress.js';
  import {createDataRowTile,createRelationalWorkbench} from '../lib/three/assets/index.js';
  import {TABLE_GRAIN_MISSION,answerForGrainCase} from '../lib/game/table-grain-mission.js';
  let host,ready=false,loadError='',caseIndex=0,step='grain',selected='',checked=false,correct=false,completed=[];
  let renderer,scene,camera,controls,workbench,rowTiles=[],frame,resizeObserver,THREE,reducedMotion=false,lightweightMode=false;
  $: caseRecord=TABLE_GRAIN_MISSION.cases[caseIndex];
  $: missionComplete=completed.length===TABLE_GRAIN_MISSION.cases.length;
  $: options=caseRecord?(step==='grain'?caseRecord.grainOptions:caseRecord.countOptions):[];
  $: question=step==='grain'?'Complete the sentence: one row represents…':'If we count the rows, what have we counted?';
  $: theory=step==='grain'?'A table’s grain is the precise meaning of one row. State every entity, place, and time component needed to distinguish one observation.':'COUNT(*) counts records at the table’s existing grain. It does not automatically count distinct entities or add a quantity column.';
  $: progress=Math.round(((completed.length*2+(step==='count'?1:0)+(correct?1:0))/(TABLE_GRAIN_MISSION.cases.length*2))*100);
  $: if (missionComplete) recordCompletion('table-grain');

  function placeRows(){
    if(!scene||!workbench||!caseRecord)return;
    rowTiles.forEach(tile=>{scene.remove(tile.group);tile.dispose()});rowTiles=[];
    caseRecord.rows.forEach((row,index)=>{const tile=createDataRowTile(THREE,{id:`${caseRecord.id}-${index}`,columnCount:caseRecord.columns.length,colour:caseRecord.colour});tile.group.position.copy(workbench.attachment(`row-slot-${index}`).position);tile.group.position.y+=.05;scene.add(tile.group);rowTiles.push(tile)});
    workbench.setStatus('idle');
  }
  function choose(value){if(correct)return;selected=value;checked=true;correct=value===answerForGrainCase(caseRecord,step);workbench?.setStatus(correct?'resolved':'error');rowTiles.forEach(tile=>tile.setState(correct?'resolved':'error'))}
  function continueMission(){if(!correct)return;if(step==='grain'){step='count';selected='';checked=false;correct=false;workbench?.setStatus('idle');rowTiles.forEach(tile=>tile.setState('idle'));return}completed=[...completed,caseRecord.id];caseIndex+=1;step='grain';selected='';checked=false;correct=false;if(caseIndex<TABLE_GRAIN_MISSION.cases.length)setTimeout(placeRows,0);else{workbench?.setStatus('resolved');rowTiles.forEach(tile=>{scene?.remove(tile.group);tile.dispose()});rowTiles=[]}}
  function resetMission(){caseIndex=0;step='grain';selected='';checked=false;correct=false;completed=[];setTimeout(placeRows,0)}
  onMount(async()=>{try{
    reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;lightweightMode=matchMedia('(max-width: 760px), (pointer: coarse)').matches;if(lightweightMode){reducedMotion=true;ready=true;return}THREE=await import('three');const {OrbitControls}=await import('three/addons/controls/OrbitControls.js');scene=new THREE.Scene();scene.background=new THREE.Color('#e7e0d3');scene.fog=new THREE.Fog('#e7e0d3',9,17);camera=new THREE.PerspectiveCamera(36,Math.max(host.clientWidth,1)/Math.max(host.clientHeight,1),.1,35);camera.position.set(4.9,3.7,5.4);renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(host.clientWidth,host.clientHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.shadowMap.enabled=true;renderer.domElement.setAttribute('aria-label','Interactive relational table workbench with three data row tiles');host.appendChild(renderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=false;controls.target.set(0,1,0);controls.update();workbench=createRelationalWorkbench(THREE);scene.add(workbench.group);placeRows();const floor=new THREE.Mesh(new THREE.CircleGeometry(6.5,56),new THREE.MeshStandardMaterial({color:0xd6cebd,roughness:.96}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor,new THREE.HemisphereLight(0xfffbef,0x65625b,2.2));const key=new THREE.DirectionalLight(0xffffff,2.6);key.position.set(4,7,4);key.castShadow=true;scene.add(key);resizeObserver=new ResizeObserver(()=>{if(!host.clientWidth||!host.clientHeight)return;camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight,false)});resizeObserver.observe(host);ready=true;const render=now=>{frame=requestAnimationFrame(render);controls.update();if(!reducedMotion)rowTiles.forEach((tile,index)=>tile.group.rotation.y=Math.sin(now*.0012+index)*.006);renderer.render(scene,camera)};frame=requestAnimationFrame(render)
  }catch(error){loadError='The relational workbench could not start on this device.';console.error(error)}});
  onDestroy(()=>{if(frame)cancelAnimationFrame(frame);resizeObserver?.disconnect();controls?.dispose();rowTiles.forEach(tile=>tile.dispose());workbench?.dispose();scene?.traverse(o=>{if(workbench?.group?.getObjectById(o.id)||rowTiles.some(tile=>tile.group.getObjectById(o.id)))return;o.geometry?.dispose();o.material?.dispose?.()});renderer?.dispose();renderer?.domElement?.remove()});
</script>

<svelte:head><title>What Does One Row Represent? | Qubix University</title><meta name="description" content="Local AI draft of the Qubix Superstore table-grain mission." /></svelte:head>
<section class="mission-shell qx-shell">
  <header><div class="identity"><span class="role">PRE<br/>INTERN</span><div><p>{TABLE_GRAIN_MISSION.id} · {TABLE_GRAIN_MISSION.status}</p><h1>{TABLE_GRAIN_MISSION.title}</h1></div></div><nav><a href="?mode=game&mission=foundations">Foundations</a><a href="?mode=game&mission=missing-data">Mission 003</a><a href="?mode=assets&asset=relational-workbench">New assets</a><a href="?mode=wiki">Library</a></nav></header>
  <div class="progress" aria-label={`Mission ${progress}% complete`}><span style={`width:${progress}%`}></span></div>
  <main>
    <section class="stage-card"><div class="stage-heading"><div><p class="eyebrow">CORPORATE HQ · RELATIONAL DESK</p><h2>{missionComplete?'Table review complete':caseRecord.table}</h2></div><span>{missionComplete?'6 / 6':`${caseIndex+1} / ${TABLE_GRAIN_MISSION.cases.length}`}</span></div>{#if !lightweightMode}<div class="viewport" bind:this={host}>{#if !ready&&!loadError}<div class="loading">Opening relational workbench…</div>{/if}{#if loadError}<div class="loading" role="alert">{loadError}</div>{/if}</div>{/if}
      {#if !missionComplete}<div class="table-wrap"><table><thead><tr>{#each caseRecord.columns as column}<th>{column}</th>{/each}</tr></thead><tbody>{#each caseRecord.rows as row}<tr>{#each row as value}<td>{value}</td>{/each}</tr>{/each}</tbody></table></div>{/if}
    </section>
    <aside class="decision-card">
      {#if missionComplete}<div class="completion"><span>✓</span><p class="eyebrow">COMPETENCY DEMONSTRATED</p><h2>Six grains documented</h2><p>{TABLE_GRAIN_MISSION.competency}</p><ul>{#each TABLE_GRAIN_MISSION.cases as item}<li><b>{item.table}</b><span>{item.grain}</span></li>{/each}</ul><a class="next-mission" href="?mode=game&mission=duplicate-records">Continue to Mission 005</a><button on:click={resetMission}>Run mission again</button></div>
      {:else}<div class="theory"><p class="eyebrow">THEORY → PRACTICAL · {step==='grain'?'GRAIN':'ROW COUNT'}</p><h2>{question}</h2><p>{theory}</p></div><article class="evidence"><p>{caseRecord.context}</p><code>{caseRecord.rows.length} sample rows · {caseRecord.columns.length} variables</code></article><div class="options">{#each options as option}<button class:selected={selected===option} class:right={correct&&selected===option} class:wrong={checked&&!correct&&selected===option} on:click={()=>choose(option)} disabled={correct}><b>{option}</b></button>{/each}</div>{#if checked}<div class:success={correct} class:retry={!correct} class="feedback" role="status">{#if correct}<b>Correct.</b> {step==='grain'?caseRecord.explanation:caseRecord.countExplanation}{:else}<b>Try again.</b> Name exactly what changes from one legitimate row to the next.{/if}</div>{/if}{#if correct}<button class="continue" on:click={continueMission}>{step==='grain'?'Interpret the row count':caseIndex===TABLE_GRAIN_MISSION.cases.length-1?'Complete mission':'Inspect next table'} →</button>{/if}{/if}
    </aside>
  </main>
  <footer><span>Source-informed learning draft · accessed 21 August 2026</span><span>{#each TABLE_GRAIN_MISSION.sources as source,index}<a href={source.url} target="_blank" rel="noreferrer">{source.label}</a>{index<TABLE_GRAIN_MISSION.sources.length-1?' · ':''}{/each}</span></footer>
</section>

<style>
  :global(html),:global(body){overflow:auto;background:#171510}:global(body){position:static}.mission-shell{min-height:100vh;max-width:none;padding:18px clamp(12px,3vw,34px) 30px;background:radial-gradient(circle at 42% 0,#3f3428,#171510 58%);overflow:auto;color:#f1ede4}header{max-width:1320px;margin:0 auto 14px;display:flex;align-items:center;justify-content:space-between;gap:16px}.identity{display:flex;align-items:center;gap:12px}.role{display:grid;place-items:center;width:48px;height:48px;border-radius:13px;background:#a85a34;color:white;font:900 9px/1.15 var(--qx-font);text-align:center}.identity p{margin:0 0 3px;color:#bcb19e;font:800 9px var(--qx-font);letter-spacing:.1em}.identity h1{margin:0;color:white;font:700 26px Georgia,serif}nav{display:flex;gap:14px}nav a,footer a{color:#e2c7b7;font:800 11px var(--qx-font);text-decoration:none;border-bottom:1px solid currentColor;padding-bottom:3px}.progress{max-width:1320px;height:5px;margin:0 auto 16px;border-radius:8px;background:rgba(255,255,255,.1);overflow:hidden}.progress span{display:block;height:100%;background:#63b13b;transition:width .35s ease}main{max-width:1320px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1.18fr) minmax(360px,.82fr);gap:16px;align-items:start}.stage-card,.decision-card{border:1px solid rgba(255,255,255,.12);border-radius:18px;background:#f1ede4;color:#25231f;overflow:hidden}.stage-heading{min-height:76px;padding:15px 18px;display:flex;align-items:center;justify-content:space-between}.stage-heading h2{margin:1px 0 0;font:700 22px Georgia,serif}.stage-heading>span{display:grid;place-items:center;min-width:52px;height:34px;border-radius:20px;background:#25231f;color:white;font:900 10px var(--qx-font)}.eyebrow{margin:0 0 5px;color:#8c4c2e;font:900 9px var(--qx-font);letter-spacing:.12em}.viewport{position:relative;min-height:clamp(380px,51vh,570px);background:#e7e0d3;border-block:1px solid #d4cbb9;overflow:hidden;touch-action:none}.viewport :global(canvas){display:block;width:100%;height:100%}.loading{position:absolute;inset:0;display:grid;place-items:center;color:#6e6655;font:800 12px var(--qx-font)}.table-wrap{overflow-x:auto;padding:13px;background:#fbf8f1}.table-wrap table{width:100%;border-collapse:collapse;white-space:nowrap}.table-wrap th,.table-wrap td{padding:8px 10px;border:1px solid #d8d0be;text-align:left;font:700 9.5px var(--qx-font)}.table-wrap th{background:#28251f;color:white;font-size:9px}.table-wrap td{color:#4e473b}.decision-card{padding:clamp(18px,2.5vw,29px);overflow:visible}.theory{padding-bottom:16px;border-bottom:1px solid #d8d0be}.theory h2,.completion h2{margin:0;font:700 24px Georgia,serif}.theory>p:last-child,.completion>p{margin:8px 0 0;color:#625a49;font:600 12.5px/1.5 var(--qx-font)}.evidence{margin:14px 0;padding:13px;border-radius:11px;background:#fbf8f1;border:1px solid #ddd5c5}.evidence p{margin:0 0 8px;font:650 12px/1.45 var(--qx-font)}.evidence code{color:#8c4c2e;font:800 10.5px var(--qx-font)}.options{display:grid;gap:8px}.options button{min-height:54px;padding:10px 12px;border:2px solid #ded6c6;border-radius:11px;background:white;color:#25231f;text-align:left;cursor:pointer}.options button b{font:850 11.5px/1.35 var(--qx-font)}.options button:hover,.options button.selected{border-color:#a85a34}.options button.right{border-color:#559535;background:#e7f0df}.options button.wrong{border-color:#b83a29;background:#f6ddd8}.options button:focus-visible,.continue:focus-visible,.completion button:focus-visible,.next-mission:focus-visible{outline:3px solid #a85a34;outline-offset:2px}.options button:disabled{cursor:default}.feedback{margin-top:11px;padding:11px 12px;border-radius:10px;font:650 11.5px/1.45 var(--qx-font)}.feedback.success{background:#e7f0df;color:#3d6529}.feedback.retry{background:#f6ddd8;color:#912c1e}.continue,.completion button,.next-mission{width:100%;min-height:46px;margin-top:11px;border:0;border-radius:11px;background:#a85a34;color:white;font:900 11.5px var(--qx-font);cursor:pointer}.next-mission{display:grid;place-items:center;box-sizing:border-box;background:#25231f;text-decoration:none}.completion{text-align:center}.completion>span{display:grid;place-items:center;width:58px;height:58px;margin:10px auto 14px;border-radius:50%;background:#559535;color:white;font:900 26px var(--qx-font)}.completion ul{list-style:none;margin:20px 0 0;padding:0;border:1px solid #d8d0be;border-radius:11px;overflow:hidden;text-align:left}.completion li{display:grid;grid-template-columns:110px 1fr;gap:12px;padding:10px 12px;border-bottom:1px solid #ddd5c5;font:700 10.5px var(--qx-font)}.completion li:last-child{border-bottom:0}.completion li span{color:#706856}footer{max-width:1320px;margin:14px auto 0;display:flex;justify-content:space-between;gap:14px;color:#9f9585;font:650 9px/1.5 var(--qx-font)}footer a{font-size:9px}@media(max-width:940px){main{grid-template-columns:1fr}.viewport{min-height:480px}footer{flex-direction:column}}@media(max-width:600px){.mission-shell{padding:13px 10px 25px}header{align-items:flex-start}.identity h1{font-size:20px}.role{width:42px;height:42px}nav{flex-direction:column;align-items:flex-end;gap:6px}.viewport{min-height:350px}.decision-card{padding:16px}.completion li{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.progress span{transition:none}}
</style>
